"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { ChevronRight, MoreHorizontal } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"
import { PriorityBadge, type PriorityLevel } from "@/components/ui/priority-badge"

export type AttentionChip =
  | { type: "priority"; level: PriorityLevel; label?: string }
  | { type: "date"; label: string }
  | { type: "status"; label: string; tone?: "neutral" | "good" | "bad" }
  | { type: "progress"; done: number; total: number }
  | { type: "text"; label: string }

export type AttentionAction = {
  id: string
  label: string
  onSelect: () => void
}

export type AttentionItem = {
  id: string
  title: string
  description?: string
  tone?: "critical" | "neutral" | "positive"
  chips?: readonly AttentionChip[]
  href?: string
  onSelect?: (item: AttentionItem) => void
  actions?: readonly AttentionAction[]
  /** Cells for layout="table", keyed by column id. */
  cells?: Record<string, React.ReactNode>
}

export type AttentionListClassNames = {
  root?: string
  item?: string
  title?: string
  description?: string
  empty?: string
}

export type AttentionColumn = { id: string; label: string; mono?: boolean }

export type AttentionListProps = {
  items: readonly AttentionItem[]
  label?: string
  layout?: "stack" | "table" | "compact"
  columns?: readonly AttentionColumn[]
  max?: number
  moreLabel?: (hidden: number) => string
  emptyLabel?: string
  emptyHint?: string
  loading?: boolean
  loadingRows?: number
  className?: string
  classNames?: AttentionListClassNames
}

const tileClass = {
  critical: "bg-destructive/10 text-destructive",
  neutral: "bg-muted text-muted-foreground",
  positive: "bg-chart-2/20 text-foreground",
} as const

function chipText(chip: AttentionChip): string {
  if (chip.type === "priority") return chip.label ?? chip.level
  if (chip.type === "progress") return `${chip.done} of ${chip.total}`
  return chip.label
}

function rowName(item: AttentionItem): string {
  const chips = (item.chips ?? []).map(chipText).filter(Boolean)
  return [item.title, ...chips].join(", ")
}

function Chips({ chips }: { chips: readonly AttentionChip[] }) {
  return (
    <div className="flex flex-wrap gap-1" aria-hidden>
      {chips.map((chip, index) => {
        if (chip.type === "priority") return <PriorityBadge key={`${chip.level}-${index}`} level={chip.level} label={chip.label} />
        const tone = chip.type === "status" ? chip.tone : undefined
        return (
          <span
            key={`${chip.type}-${index}`}
            className={cn(
              "inline-flex h-6 max-w-full items-center rounded-full bg-muted px-2 text-xs text-foreground",
              tone === "good" && "bg-chart-2/20",
              tone === "bad" && "bg-destructive/10 text-destructive",
              chip.type === "progress" && "bg-chart-2/15",
            )}
          >
            <span className="truncate">{chipText(chip)}</span>
          </span>
        )
      })}
    </div>
  )
}

export function AttentionList({
  items,
  label = "Needs you",
  layout = "stack",
  columns = [],
  max,
  moreLabel = (hidden) => `Show ${hidden} more`,
  emptyLabel = "You're all caught up",
  emptyHint = "Nothing is waiting on you.",
  loading = false,
  loadingRows = 3,
  className,
  classNames,
}: AttentionListProps) {
  const [open, setOpen] = React.useState(false)
  const visible = max != null && !open ? items.slice(0, max) : items
  const hidden = items.length - visible.length

  function onRowKey(event: React.KeyboardEvent<HTMLElement>, index: number) {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return
    const rows = event.currentTarget.closest("ul")?.querySelectorAll<HTMLElement>("[data-attention-row]")
    if (!rows?.length) return
    event.preventDefault()
    const next = event.key === "ArrowDown" ? Math.min(rows.length - 1, index + 1) : Math.max(0, index - 1)
    rows[next]?.focus()
  }

  return (
    <div data-slot="attention-list" className={cn("min-w-0", className, classNames?.root)}>
      {loading ? (
        <ul className="flex flex-col gap-3" aria-busy="true" aria-label={label}>
          {Array.from({ length: loadingRows }, (_, index) => (
            <li key={index} className="flex gap-3">
              <Skeleton className="size-8 shrink-0" />
              <div className="flex flex-1 flex-col gap-2">
                <Skeleton className="h-4 w-2/3" />
                <Skeleton className="h-3 w-full" />
              </div>
            </li>
          ))}
        </ul>
      ) : items.length === 0 ? (
        <div className={cn("flex flex-col items-start gap-1 py-4", classNames?.empty)}>
          <p className="text-sm font-medium">{emptyLabel}</p>
          <p className="text-xs text-muted-foreground">{emptyHint}</p>
        </div>
      ) : (
        layout === "table" && columns.length ? (
          <div className="min-w-0 overflow-x-auto">
            <table className="w-full min-w-[36rem] border-separate border-spacing-0 text-sm">
              <thead>
                <tr className="bg-muted text-xs text-muted-foreground">
                  {columns.map((column) => (
                    <th key={column.id} className="px-3 py-2 text-start font-medium first:rounded-s-lg last:rounded-e-lg">
                      {column.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {visible.map((item, index) => {
                  const name = rowName(item)
                  return (
                    <tr
                      key={item.id}
                      data-attention-row=""
                      tabIndex={0}
                      className="cursor-pointer border-b border-border hover:bg-muted/70 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      onClick={() => item.onSelect?.(item)}
                      onKeyDown={(event) => {
                        if (event.key === "Enter" || event.key === " ") {
                          event.preventDefault()
                          item.onSelect?.(item)
                        }
                        onRowKey(event, index)
                      }}
                    >
                      {columns.map((column) => (
                        <td key={column.id} className={cn("border-b border-border px-3 py-3 align-middle", column.mono && "font-mono text-xs")}>
                          {item.cells?.[column.id] ?? (column.id === columns[0]?.id ? item.title : null)}
                        </td>
                      ))}
                      <td className="sr-only">{name}</td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        ) : layout === "compact" ? (
          <ul role="list" aria-label={label} className="flex flex-col">
            {visible.map((item, index) => (
              <li key={item.id}>
                <button
                  type="button"
                  data-attention-row=""
                  className="flex w-full items-center gap-2 rounded-lg px-2 py-2 text-start hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  onClick={() => item.onSelect?.(item)}
                  onKeyDown={(event) => onRowKey(event, index)}
                >
                  <span
                    aria-hidden
                    className={cn(
                      "size-2 shrink-0 rounded-full",
                      item.tone === "critical" && "bg-destructive",
                      item.tone === "positive" && "bg-primary",
                      (item.tone ?? "neutral") === "neutral" && "bg-chart-4",
                    )}
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-sm font-medium">{item.title}</span>
                    {item.description ? <span className="block truncate text-xs text-muted-foreground">{item.description}</span> : null}
                  </span>
                  <ChevronRight className="size-4 shrink-0 text-muted-foreground" aria-hidden />
                </button>
              </li>
            ))}
          </ul>
        ) : (
        <ul role="list" aria-label={label} className="flex flex-col">
          {visible.map((item, index) => {
            const tone = item.tone ?? "neutral"
            const name = rowName(item)
            const interactive = Boolean(item.href || item.onSelect)
            const body = (
              <>
                <span className={cn("grid size-8 shrink-0 place-items-center rounded-lg text-xs font-medium", tileClass[tone])} aria-hidden>
                  {index + 1}
                </span>
                <span className="min-w-0 flex-1">
                  <span className={cn("block truncate text-sm font-medium", classNames?.title)}>{item.title}</span>
                  {item.description ? (
                    <span className={cn("mt-0.5 line-clamp-2 block text-xs text-muted-foreground", classNames?.description)}>
                      {item.description}
                    </span>
                  ) : null}
                  {item.chips?.length ? (
                    <span className="mt-2 block">
                      <Chips chips={item.chips} />
                    </span>
                  ) : null}
                </span>
                {interactive ? <ChevronRight className="size-4 shrink-0 text-muted-foreground" aria-hidden /> : null}
              </>
            )
            const rowClass = cn(
              "flex w-full min-w-0 items-start gap-3 rounded-lg py-3 text-start hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              index > 0 && "border-t border-border",
              classNames?.item,
            )
            return (
              <li key={item.id} className="flex min-w-0 items-start gap-1">
                {item.href ? (
                  <a
                    data-attention-row=""
                    href={item.href}
                    aria-label={name}
                    className={cn(rowClass, "flex-1")}
                    onClick={(event) => {
                      if (!item.onSelect) return
                      event.preventDefault()
                      item.onSelect(item)
                    }}
                    onKeyDown={(event) => onRowKey(event, index)}
                  >
                    {body}
                  </a>
                ) : interactive ? (
                  <button
                    data-attention-row=""
                    type="button"
                    aria-label={name}
                    className={cn(rowClass, "flex-1")}
                    onClick={() => item.onSelect?.(item)}
                    onKeyDown={(event) => onRowKey(event, index)}
                  >
                    {body}
                  </button>
                ) : (
                  <div className={cn(rowClass, "flex-1")}>{body}</div>
                )}
                {item.actions?.length ? (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button type="button" variant="ghost" size="icon-sm" className="mt-2 shrink-0" aria-label={`Actions for ${item.title}`}>
                        <MoreHorizontal />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      {item.actions.map((action) => (
                        <DropdownMenuItem key={action.id} onSelect={() => action.onSelect()}>
                          {action.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                ) : null}
              </li>
            )
          })}
        </ul>
        )
      )}
      {hidden > 0 ? (
        <Button type="button" variant="ghost" size="sm" className="mt-1" onClick={() => setOpen(true)}>
          {moreLabel(hidden)}
        </Button>
      ) : null}
    </div>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { formatDashboardValue, shareOf, type DashboardFormat } from "@/lib/dashboard-format"

export type BreakdownSegment = {
  id: string
  label: string
  value: number
}

export type BreakdownBarClassNames = {
  root?: string
  total?: string
  track?: string
  legend?: string
}

export type BreakdownBarProps = {
  total: number
  segments: readonly BreakdownSegment[]
  label?: string
  format?: DashboardFormat
  locale?: string
  currency?: string
  /** legend is the default list. pipeline draws gapped stages with counts underneath. */
  variant?: "legend" | "pipeline"
  /** Segment index drawn in the accent. The last segment stays inverted. */
  emphasis?: number
  heading?: string
  caption?: string
  action?: { label: string; onSelect: () => void }
  className?: string
  classNames?: BreakdownBarClassNames
}

const segmentClass = ["bg-primary", "bg-chart-2", "bg-chart-3", "bg-chart-4", "bg-chart-5"]

export function BreakdownBar({
  total,
  segments,
  label = "Breakdown",
  format = "currency",
  locale = "en-US",
  currency = "USD",
  variant = "legend",
  emphasis,
  heading,
  caption,
  action,
  className,
  classNames,
}: BreakdownBarProps) {
  const reduced = useReducedMotion() ?? false
  const [active, setActive] = React.useState<string | null>(null)
  const sum = segments.reduce((acc, segment) => acc + Math.max(0, segment.value), 0)
  const basis = sum > 0 ? sum : Math.max(total, 0)
  const summary = segments
    .map((segment) => `${segment.label} ${formatDashboardValue(segment.value, format, locale, currency)}`)
    .join(", ")

  if (variant === "pipeline") {
    return (
      <div data-slot="breakdown-bar" data-variant="pipeline" className={cn("flex min-w-0 flex-col gap-3", className, classNames?.root)}>
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm font-medium">{heading ?? label}</p>
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            {caption ? <span>{caption}</span> : null}
            {action ? (
              <button type="button" className="font-medium text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none" onClick={action.onSelect}>
                {action.label}
              </button>
            ) : null}
          </div>
        </div>
        <div role="img" aria-label={`${label}: ${summary}`} className={cn("flex h-3 gap-1", classNames?.track)}>
          {segments.map((segment, index) => {
            const share = shareOf(Math.max(0, segment.value), basis)
            const last = index === segments.length - 1
            const hot = emphasis === index
            return (
              <span
                key={segment.id}
                data-segment={segment.id}
                className="h-full min-w-1 origin-left"
                style={{ width: `${Math.max(share * 100, share > 0 ? 6 : 0)}%` }}
              >
                <span
                  className={cn(
                    "block h-full rounded-full motion-safe:animate-in motion-safe:slide-in-from-left-2",
                    reduced && "animate-none",
                    hot ? "bg-primary" : last ? "bg-foreground" : "bg-muted-foreground/25",
                  )}
                />
              </span>
            )
          })}
        </div>
        <div className="flex gap-1">
          {segments.map((segment) => {
            const share = shareOf(Math.max(0, segment.value), basis)
            return (
              <div key={segment.id} className="min-w-0" style={{ width: `${Math.max(share * 100, share > 0 ? 6 : 0)}%` }}>
                <p className="font-mono text-sm tabular-nums">{formatDashboardValue(segment.value, "number", locale)}</p>
                <p className="truncate text-[10px] text-muted-foreground">{segment.label}</p>
              </div>
            )
          })}
        </div>
      </div>
    )
  }

  return (
    <div data-slot="breakdown-bar" className={cn("flex min-w-0 flex-col gap-3", className, classNames?.root)}>
      <p className={cn("text-4xl font-normal tabular-nums tracking-tight break-words", classNames?.total)}>
        {formatDashboardValue(total, format, locale, currency)}
      </p>
      <div
        data-slot="breakdown-track"
        role="img"
        aria-label={`${label}: ${summary}`}
        className={cn("flex h-2.5 gap-0.5 overflow-hidden rounded-full bg-muted", classNames?.track)}
      >
        {segments.map((segment, index) => {
          const share = shareOf(Math.max(0, segment.value), basis)
          const dim = active != null && active !== segment.id
          return (
            <span
              key={segment.id}
              data-segment={segment.id}
              data-dim={dim ? "true" : undefined}
              className={cn("h-full min-w-1 rounded-full transition-opacity motion-reduce:transition-none data-[dim=true]:opacity-40", segmentClass[index % segmentClass.length])}
              style={{ width: `${Math.max(share * 100, share > 0 ? 4 : 0)}%` }}
            />
          )
        })}
      </div>
      <ul className={cn("flex flex-col", classNames?.legend)}>
        {segments.map((segment, index) => {
          const share = shareOf(Math.max(0, segment.value), basis)
          const dim = active != null && active !== segment.id
          return (
            <li key={segment.id}>
              <button
                type="button"
                className="flex w-full items-center gap-2 rounded-md py-1.5 text-start text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                aria-pressed={active === segment.id}
                onMouseEnter={() => setActive(segment.id)}
                onMouseLeave={() => setActive(null)}
                onFocus={() => setActive(segment.id)}
                onBlur={() => setActive(null)}
              >
                <span className={cn("size-2 shrink-0 rounded-full", segmentClass[index % segmentClass.length])} aria-hidden />
                <span className={cn("min-w-0 flex-1 truncate", dim && "opacity-40")}>{segment.label}</span>
                <span className="shrink-0 tabular-nums">
