export type PromptSuggestionsProps = {
  items: PromptSuggestion[]
  onSelect?: (value: string) => void
  layout?: "scroll" | "wrap"
  loading?: boolean
  label?: string
  className?: string
  classNames?: PromptSuggestionsClassNames
}

function normalize(item: PromptSuggestion) {
  if (typeof item === "string") return { label: item, value: item, icon: null }
  return { label: item.label, value: item.value ?? item.label, icon: item.icon ?? null }
}

export function PromptSuggestions({
  items,
  onSelect,
  layout = "wrap",
  loading = false,
  label = "Suggestions",
  className,
  classNames,
}: PromptSuggestionsProps) {
  const normalized = items.map(normalize)
  const [active, setActive] = React.useState(0)

  if (loading) {
    return (
      <div className={cn("flex gap-2", className)} aria-hidden="true">
        <Skeleton className="h-7 w-24 rounded-full" />
        <Skeleton className="h-7 w-28 rounded-full" />
        <Skeleton className="h-7 w-20 rounded-full" />
      </div>
    )
  }

  if (normalized.length === 0) return null

  return (
    <div
      role="list"
      aria-label={label}
      className={cn(
        layout === "scroll"
          ? "flex snap-x gap-2 overflow-x-auto [mask-image:linear-gradient(to_right,transparent,black_12px,black_calc(100%-12px),transparent)]"
          : "flex flex-wrap gap-2",
        className,
        classNames?.root,
      )}
      onKeyDown={(event) => {
        if (layout !== "scroll") return
        if (event.key !== "ArrowRight" && event.key !== "ArrowLeft") return
        event.preventDefault()
        const delta = event.key === "ArrowRight" ? 1 : -1
        const next = (active + delta + normalized.length) % normalized.length
        setActive(next)
        document.getElementById(`suggestion-${next}`)?.focus()
      }}
    >
      {normalized.map((item, index) => (
        <div role="listitem" key={`${item.value}-${index}`} className="snap-start">
          <Button
            id={layout === "scroll" ? `suggestion-${index}` : undefined}
            type="button"
            variant="outline"
            size="sm"
            tabIndex={layout === "scroll" ? (index === active ? 0 : -1) : 0}
            className={cn("max-w-[240px] rounded-full", classNames?.item)}
            onClick={() => onSelect?.(item.value)}
            onFocus={() => setActive(index)}
          >
            {item.icon}
            <span className="truncate">{item.label}</span>
          </Button>
        </div>
      ))}
    </div>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { clampRatio, formatDashboardValue, type DashboardFormat } from "@/lib/dashboard-format"

export type RadialGaugeTone = "primary" | "neutral" | "destructive"

export type RadialGaugeClassNames = {
  root?: string
  value?: string
  label?: string
  over?: string
  ticks?: string
}

export type RadialGaugeProps = {
  value: number
  min?: number
  max?: number
  /** Accessible name for the meter. */
  label: string
  ticks?: number
  format?: DashboardFormat
  formatter?: (value: number) => string
  locale?: string
  currency?: string
  overLabel?: string
  tone?: RadialGaugeTone
  /** arc keeps the needle. ticks is a needle-less semicircle of marks. */
  variant?: "arc" | "ticks"
  /** Shown after the value on the ticks variant, for example "%". */
  suffix?: string
  className?: string
  classNames?: RadialGaugeClassNames
}

const CX = 100
const CY = 96
const RADIUS = 74

function point(angle: number, radius: number) {
  return {
    x: CX + Math.cos(angle) * radius,
    y: CY - Math.sin(angle) * radius,
  }
}

function arcPath(radius: number) {
  const start = point(Math.PI, radius)
  const end = point(0, radius)
  return `M ${start.x.toFixed(2)} ${start.y.toFixed(2)} A ${radius} ${radius} 0 0 1 ${end.x.toFixed(2)} ${end.y.toFixed(2)}`
}

const toneClass: Record<RadialGaugeTone, string> = {
  primary: "stroke-primary text-primary",
  neutral: "stroke-muted-foreground text-muted-foreground",
  destructive: "stroke-destructive text-destructive",
}

export function RadialGauge({
  value,
  min = 0,
  max = 100,
  label,
  ticks = 5,
  format = "number",
  formatter,
  locale = "en-US",
  currency = "USD",
  overLabel = "Over budget",
  tone = "primary",
  variant = "arc",
  suffix,
  className,
  classNames,
}: RadialGaugeProps) {
  const safeMax = max > min ? max : min + 1
  const over = value > max
  const ratio = clampRatio(value, min, safeMax)
  const clamped = value < min || value > max
  const angle = Math.PI * (1 - ratio)
  const needle = point(angle, RADIUS - 10)
  const hub = point(angle, 8)
  const text = formatter ? formatter(value) : formatDashboardValue(value, format, locale, currency)
  const tickCount = variant === "ticks" ? Math.max(12, Math.min(48, Math.round(ticks))) : Math.max(2, Math.min(9, Math.round(ticks)))
  const marks = Array.from({ length: tickCount }, (_, index) => {
    const at = Math.PI * (1 - index / (tickCount - 1))
    const outer = point(at, RADIUS + 2)
    const inner = point(at, RADIUS - 8)
    return { outer, inner, key: index }
  })
  const valuetext = over ? `${text}, ${overLabel}` : text
  const filledTicks = Math.round(ratio * tickCount)

  if (variant === "ticks") {
    return (
      <div
        data-slot="radial-gauge"
        data-variant="ticks"
        data-state={over ? "over" : "ok"}
        data-tone={over ? "destructive" : tone}
        role="meter"
        aria-label={label}
        aria-valuenow={value}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={valuetext}
        className={cn("@container flex min-w-0 flex-col items-center gap-1 text-foreground", className, classNames?.root)}
      >
        <svg viewBox="0 0 200 118" className="h-auto w-full max-w-xs" aria-hidden>
          <g className={classNames?.ticks}>
            {marks.map((mark) => (
              <line
                key={mark.key}
                x1={mark.inner.x}
                y1={mark.inner.y}
                x2={mark.outer.x}
                y2={mark.outer.y}
                className={mark.key < filledTicks ? "stroke-foreground" : "stroke-muted-foreground/30"}
                strokeWidth="2.5"
                strokeLinecap="round"
              />
            ))}
          </g>
        </svg>
        <p className={cn("text-3xl font-normal tabular-nums tracking-tight", over && "text-destructive", classNames?.value)}>
          {text}
          {suffix ? <span className="align-super text-sm">{suffix}</span> : null}
        </p>
        <p className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</p>
      </div>
    )
  }

  return (
    <div
      data-slot="radial-gauge"
      data-state={over ? "over" : "ok"}
      data-tone={over ? "destructive" : tone}
      role="meter"
      aria-label={label}
      aria-valuenow={value}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={valuetext}
      className={cn("@container flex min-w-0 flex-col items-center gap-1 text-foreground", className, classNames?.root)}
    >
      <svg viewBox="0 0 200 118" className="h-auto w-full max-w-xs" aria-hidden>
        <path d={arcPath(RADIUS)} className="fill-none stroke-muted" strokeWidth="8" strokeLinecap="round" />
        <path
          d={arcPath(RADIUS)}
          pathLength={100}
          className={cn("fill-none", over ? "stroke-destructive" : toneClass[tone])}
          strokeWidth="8"
          strokeLinecap="round"
          strokeDasharray={`${ratio * 100} 100`}
        />
        <g className={classNames?.ticks}>
          {marks.map((mark) => (
            <line
              key={mark.key}
              x1={mark.inner.x}
              y1={mark.inner.y}
              x2={mark.outer.x}
              y2={mark.outer.y}
              className="stroke-muted-foreground"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          ))}
        </g>
        <line
          data-slot="radial-gauge-needle"
          data-clamped={clamped ? "true" : "false"}
          x1={hub.x}
          y1={hub.y}
          x2={needle.x}
          y2={needle.y}
          className={over ? "stroke-destructive" : "stroke-foreground"}
          strokeWidth="2.5"
          strokeLinecap="round"
        />
        <circle cx={CX} cy={CY} r="4" className={over ? "fill-destructive" : "fill-foreground"} />
      </svg>
      <p className={cn("text-3xl font-normal tabular-nums tracking-tight", over && "text-destructive", classNames?.value)}>{text}</p>
      <p className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</p>
      {over ? <p className={cn("text-xs font-medium text-destructive", classNames?.over)}>{overLabel}</p> : null}
    </div>
  )
}
